// Fontes da pauta diária: sites que cobrem tecnologia e o impacto dela na vida humana.
// match: como reconhecer a notícia de cada fonte pelo link (o RSS não diz de qual feed ela veio).
// weight: bônus para veículos de análise/investigação (vs. noticiário de mercado).
// Para acrescentar ou tirar uma fonte, edite esta lista (a primeira cujo match bater vale).
const feeds = [
  { name: 'MIT Technology Review Brasil', url: 'https://mittechreview.com.br/feed/', match: 'mittechreview\.com\.br', weight: 2 },
  { name: 'Nexo Jornal', url: 'https://www.nexojornal.com.br/rss.xml', match: 'nexojornal\.com\.br', weight: 1 },
  { name: 'Intercept Brasil', url: 'https://www.intercept.com.br/feed/', match: 'intercept\.com\.br', weight: 2 },
  { name: 'TecMundo', url: 'https://rss.tecmundo.com.br/feed', match: 'tecmundo', weight: 0 },
  { name: 'Canaltech', url: 'https://canaltech.com.br/rss/', match: 'canaltech\.com\.br', weight: 0 },
  { name: 'WIRED', url: 'https://www.wired.com/feed/rss', match: 'wired\.com', weight: 1 },
  { name: 'WIRED', url: 'https://www.wired.com/feed/category/security/latest/rss', match: 'wired\.com', weight: 1 },
  { name: 'MIT Technology Review', url: 'https://www.technologyreview.com/feed/', match: 'technologyreview\.com', weight: 2 },
  { name: 'Rest of World', url: 'https://restofworld.org/feed/latest', match: 'restofworld\.org', weight: 2 },
  { name: 'The Verge', url: 'https://www.theverge.com/rss/policy/index.xml', match: 'theverge\.com', weight: 2 },
  { name: 'The Verge', url: 'https://www.theverge.com/rss/science/index.xml', match: 'theverge\.com', weight: 2 },
  { name: 'Ars Technica (Tech Policy)', url: 'https://feeds.arstechnica.com/arstechnica/tech-policy', match: 'arstechnica\.com/tech-policy', weight: 2 },
  { name: 'Ars Technica', url: 'https://feeds.arstechnica.com/arstechnica/index', match: 'arstechnica\.com', weight: 0 },
];
return feeds.map(f => ({ json: f }));

// Junta as notícias de todas as fontes, tira as já usadas e ordena pela relação com o tema do
// W4K3 PR0T0C0L: vigilância, controle, big techs, IA, trabalho, direitos digitais, corpo e tecnologia.
const req = $('Extrair pedido').first().json.data || {};
const feeds = $('Fontes').all().map(i => i.json);
const today = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Sao_Paulo' });
const now = Date.now();

const dec = s => String(s || '')
  .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(n))
  .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCharCode(parseInt(n, 16)))
  .replace(/&quot;/g, '"').replace(/&apos;|&#039;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&');
const strip = h => dec(String(h || '').replace(/<(script|style)[\s\S]*?<\/\1>/gi, ' ').replace(/<\/p>/gi, '\n').replace(/<[^>]+>/g, ' '))
  .split('\n').map(l => l.replace(/\s+/g, ' ').trim()).filter(Boolean).join('\n');
const fold = s => String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
// link sem utm_*, sem barra final: para reconhecer a mesma matéria
const normLink = u => String(u || '').trim().replace(/[?&]utm_[^&#]*/g, '').replace(/[?&]$/, '').replace(/#.*$/, '').replace(/\/+$/, '').toLowerCase();
const exclude = new Set((req.exclude || []).map(normLink));

const T = (w, list) => list.map(t => [w, t]);
const terms = [
  ...T(3, ['vigilancia', 'surveillance', 'reconhecimento facial', 'facial recognition', 'biometri', 'spyware', 'pegasus',
    'palantir', 'rastreamento', 'tracking', 'privacidade', 'privacy', 'dados pessoais', 'personal data', 'vazamento',
    'data breach', 'censura', 'censorship', 'desinformacao', 'disinformation', 'misinformation', 'deepfake', 'algoritmo',
    'algorithm', 'big tech', 'monopolio', 'monopoly', 'antitrust', 'antitruste', 'policia', 'police', 'policiamento',
    'policing', 'drone', 'militar', 'military', 'neurotecnologia', 'neurotech', 'implante', 'brain-computer', 'neuralink',
    'transumanis', 'imortalidade', 'immortality', 'credito social', 'social credit', 'identidade digital', 'digital id',
    'ciberataque', 'cyberattack', 'ransomware', 'moderacao de conteudo', 'content moderation', 'entregador',
    'motorista de aplicativo', 'gig work', 'gig economy', 'precarizacao', 'automacao', 'automation', 'demissoes', 'layoffs',
    'sindicato', 'labor union', 'greve', 'strike', 'protesto', 'protest', 'ativista', 'activist', 'manipulacao',
    'manipulation', 'regulacao', 'regulation', 'regular a ia', 'bets', 'apostas']),
  ...T(2, ['inteligencia artificial', 'artificial intelligence', 'IA', 'AI', 'openai', 'chatgpt', 'meta', 'google',
    'amazon', 'microsoft', 'apple', 'tesla', 'musk', 'nvidia', 'tiktok', 'zuckerberg', 'bezos', 'altman', 'data center',
    'datacenter', 'robo', 'robot', 'hacker', 'hackers', 'trabalhadores', 'workers', 'plataforma', 'platform', 'uber', 'ifood', 'starlink',
    'satelite', 'satellite', 'dna', 'genetic', 'crispr', 'biotec', 'cripto', 'crypto', 'bitcoin', 'eleicao', 'election',
    'democracia', 'democracy', 'stf', 'congresso', 'congress', 'senado', 'senate', 'tribunal', 'court', 'lawsuit']),
  ...T(1, ['controle', 'processo', 'dados', 'data', 'lei', 'law', 'direitos', 'rights', 'governo', 'government', 'clima', 'climate', 'energia',
    'energy', 'saude', 'health', 'escola', 'school', 'criancas', 'children', 'redes sociais', 'social media']),
  ...T(-8, ['black friday', 'oferta', 'ofertas', 'desconto', 'cupom', 'promocao', 'deal', 'deals', 'melhores', 'best',
    'review', 'hands-on', 'unboxing', 'guia de compras', 'o que comprar', 'how to', 'como fazer', 'gift guide', 'presente',
    'wallpaper', 'trailer', 'gratis', 'free games', 'smartphone barato', 'vale a pena']),
  ...T(-4, ['hoje no tecmundo', 'resumo do dia', 'the download', 'newsletter', 'podcast']),
// siglas em maiúsculas (IA, AI) só valem escritas assim no texto original: "ia" também é verbo
].map(([w, t]) => [w, t, new RegExp('(^|[^a-zA-Z0-9])' + t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '([^a-zA-Z0-9]|$)'), t === t.toUpperCase() && /[A-Z]/.test(t)]);

const all = [];
for (const it of $input.all()) {
  const j = it.json || {};
  if (j.error || !j.title || !j.link) continue;
  const link = dec(j.link).trim();
  const feed = feeds.find(f => f.match && new RegExp(f.match, 'i').test(link)) || {};
  if (!/^https?:\/\/\S+$/.test(link) || exclude.has(normLink(link))) continue;
  const ts = Date.parse(j.isoDate || j.pubDate || '') || 0;
  const title = dec(j.title).replace(/\s+/g, ' ').trim();
  const text = strip(j['content:encoded'] || j.content || '');
  const summary = strip(j.contentSnippet || j.summary || j.content || '').replace(/\n/g, ' ').slice(0, 600);
  const source = feed.name || (link.split('/')[2] || '').replace(/^www\./, '');
  const rawHead = ' ' + title + ' ', rawBody = ' ' + summary + ' ' + text.slice(0, 1500) + ' ';
  const head = fold(rawHead), body = fold(rawBody);
  let score = Number(feed.weight || 0);
  const hits = [];
  for (const [w, t, re, cs] of terms) {
    if (re.test(cs ? rawHead : head)) { score += w * 2; hits.push(t); }
    else if (re.test(cs ? rawBody : body)) { score += w; if (w > 0) hits.push(t); }
  }
  const age = (now - ts) / 3600000;
  if (age < 24) score += 2; else if (age < 48) score += 1;
  all.push({ title, link, source, feedUrl: feed.url || '', ts, publishedDate: ts ? new Date(ts).toISOString().slice(0, 10) : today,
    summary, text: text.slice(0, 6000), score, hits: [...new Set(hits)].slice(0, 8), age });
}

// mesma matéria em dois feeds (ex.: WIRED e WIRED Security): fica uma
const seen = new Set();
let pool = all.sort((a, b) => b.score - a.score || b.ts - a.ts).filter(n => {
  const k = normLink(n.link);
  if (seen.has(k)) return false;
  seen.add(k); return true;
});
let recent = pool.filter(n => n.ts && n.age <= 72);
if (recent.length < 3) recent = pool.filter(n => n.ts && n.age <= 24 * 7);
pool = recent;

// tema pedido no Telegram (/noticia vigilância): só as que falam dele; se nenhuma falar, avisa e segue com as gerais
const topic = String(req.topic || '').trim();
let matched = true;
if (topic) {
  const words = fold(topic).split(/[^a-z0-9]+/).filter(w => w.length >= 3);
  const hit = pool.filter(n => { const t = fold(n.title + ' ' + n.summary + ' ' + n.text); return words.some(w => t.includes(w)); });
  if (hit.length) pool = hit; else matched = false;
}
pool = pool.filter(n => n.score > 0);
if (!pool.length) throw new Error('Nenhuma notícia nova e relevante nas fontes (últimos 7 dias).');

// no máximo 2 por fonte entre as 8 primeiras, para variar
const per = {}, candidates = [];
for (const n of pool) {
  const k = n.source.split(' (')[0];  // Ars Technica e Ars Technica (Tech Policy) contam juntas
  if ((per[k] = (per[k] || 0) + 1) > 2) continue;
  candidates.push(n);
  if (candidates.length === 8) break;
}
const out = { today, topic, matched, total: all.length, candidates: candidates.map(({ ts, age, ...c }) => c) };
return [{ json: { fileContent: JSON.stringify(out, null, 2) } }];
